pub(crate) fn to_tools(defs: &[ToolDef]) -> Value {
    Value::Array(
        defs.iter()
            .map(|d| {
                json!({
                    "type": "function",
                    "function": {
                        "name": d.name,
                        "description": d.description,
                        "parameters": paigasus_helikon_core::schema::strict(&d.schema),
                    }
                })
            })
            .collect(),
    )
}

/// Translate the caller's tool-selection preference.
pub(crate) fn to_tool_choice(choice: &ToolChoice) -> Value {
    match choice {
        ToolChoice::Auto => json!("auto"),
        ToolChoice::Required => json!("required"),
        ToolChoice::None => json!("none"),
        ToolChoice::Tool { name } => json!({"type": "function", "function": {"name": name}}),
        // ToolChoice is #[non_exhaustive]; unknown future variants fall back to Auto.
        _ => json!("auto"),
    // Tools: async-openai 0.41 uses `ChatCompletionTools::Function(ChatCompletionTool)`
    // as the wrapper enum; `ChatCompletionTool` holds just `function: FunctionObject`.
    if !request.tools.is_empty() {
        let tools: Vec<ChatCompletionTools> = request
            .tools
            .iter()
            .map(|td| {
                ChatCompletionTools::Function(ChatCompletionTool {
                    function: FunctionObject {
                        name: td.name.clone(),
                        description: Some(td.description.clone()),
                        parameters: Some(to_strict_schema(&td.schema)),
                        strict: Some(true),
                    },
                })
            })
            .collect();
        builder.tools(tools);
    }

